  "query": "How does Conflux's Tree-Graph consensus improve throughput compared with older designs?",
  "summary": "Conflux's Tree-Graph protocol raises throughput mainly by keeping every block instead of discarding forks, and by decoupling block production from transaction ordering. Its reported figures (roughly thousands of TPS in its published testnet and lab results) are well above Bitcoin's (~7 TPS) and pre-Merge Ethereum's (~15 TPS). Mainnet performance is typically lower than lab results.",
  "core_mechanisms": [
    {
      "name": "Tree-Graph structure",
      "description": "Conflux combines a tree (for ordering) with a DAG (for inclusion). Each block has one parent edge that forms the tree and reference edges to other concurrent tips. Blocks are not orphaned, so work from concurrent blocks still contributes."
    },
    {
      "name": "GHOST-based pivot chain",
      "description": "A pivot chain is chosen by a GHOST-style heaviest-subtree rule. Non-pivot blocks are then ordered relative to the pivot chain, so their transactions are included rather than wasted."
    },
    {
      "name": "Higher block rate without wasted work",
      "description": "Because concurrent blocks are retained, Conflux can produce blocks faster than Nakamoto longest-chain designs, which must suppress forks through slow block intervals and conservative block sizes."
    },
    {
      "name": "Decoupled inclusion and ordering",
      "description": "Transactions can be included in blocks in parallel, and the pivot chain fixes a total order afterward. This removes the single-chain bottleneck where only one block's transactions advance per interval."
    }
  ],
  "comparisons": [
    {
      "system": "Bitcoin (longest-chain Nakamoto consensus)",
      "throughput_note": "About 7 TPS. Forked blocks are orphaned and their transactions wasted, and slow block intervals limit capacity."
    },
    {
      "system": "Ethereum PoW (pre-Merge)",
      "throughput_note": "About 15 TPS. GHOST-style uncles partially recover fork work, but uncles carry limited reward and transaction inclusion is still constrained by a single canonical chain."
    },
    {
      "system": "Kaspa (GHOSTDAG / PHANTOM)",
      "throughput_note": "A closely related DAG-based design that also keeps concurrent blocks and orders them by a k-cluster rule. It is the most direct architectural peer to Conflux's approach and reports high block rates."
    },
    {
      "system": "Solana (Proof of History with Tower BFT)",
      "throughput_note": "Achieves high TPS through a single leader pipeline and a sequencing clock rather than a DAG. It trades decentralization and hardware requirements for speed, unlike Conflux's permissionless PoW-based design."
    },
    {
      "system": "Avalanche (repeated sub-sampled voting)",
      "throughput_note": "Uses metastable voting over a DAG of transactions and is designed for high throughput with fast finality. Conflux instead relies on PoW plus DAG-based ordering."
    }
  ],
