{
  "query": "How does Conflux’s Tree-Graph consensus improve throughput compared with older designs?",
  "summary": "Conflux's Tree-Graph consensus mechanism overcomes the scalability trilemma inherent in traditional linear blockchains by utilizing a Directed Acyclic Graph (DAG) structure that processes blocks concurrently rather than discarding orphan blocks. By combining parent edges (spanning tree) with reference edges (graph) and governing them via the GHAST (Greedy Heaviest Adaptive SubTree) protocol, Conflux eliminates the throughput bottlenecks of Nakamoto consensus without sacrificing decentralization or Proof-of-Work (PoW) security.",
  "core_limitations_of_legacy_designs": {
    "linear_bottlenecks": "Traditional Proof-of-Work blockchains like Bitcoin and early Ethereum enforce a strictly linear chain where only one block per round is accepted. If two miners generate valid blocks simultaneously, one becomes an 'orphan' (or uncle) and is discarded.",
    "security_tradeoff": "In legacy designs, increasing block sizes or lowering block intervals drastically elevates the fork rate. High orphan rates lower the cost of a 51% double-spend attack, forcing networks like Bitcoin (10-minute intervals, ~7 TPS) and Ethereum (12-second slots, ~15-30 TPS) to deliberately throttle throughput."
  },
  "tree_graph_architectural_solutions": {
    "dual_edge_structure": "Conflux blocks maintain two types of edges: 'Parent Edges' forming an underlying Directed Tree (establishing lineage and epoch structures) and 'Reference Edges' acknowledging other concurrent, non-conflicting blocks, forming a comprehensive DAG.",
    "zero_orphan_waste": "Instead of throwing away concurrent blocks, the Tree-Graph incorporates every valid block produced by miners into the ledger. This allows the network to safely reduce block generation intervals to under 0.5 seconds without wasting computational power or network bandwidth.",
    "deterministic_linearization_via_ghast": "To establish a definitive transaction execution order, Conflux applies GHAST (Greedy Heaviest Adaptive SubTree). GHAST deterministically linearizes all DAG blocks into a consistent global sequence by choosing the heaviest subtree path while dynamically weighting blocks to thwart liveness and pivot-racing attacks."
  },
  "throughput_performance_gains": {
    "target_tps": "Conflux achieves a throughput of 3,000 to 4,000+ Transactions Per Second (TPS) with 23-second confirmation latencies on its Layer 1, compared to Ethereum's 15-30 TPS and Bitcoin's 7 TPS.",
    "bandwidth_saturation": "Because the network handles concurrent block proposals without chain splits, Conflux can saturate network bandwidth and processing limits up to real-world node capacity."
  },
  "competitor_comparisons": [
    {
      "competitor": "Bitcoin & Ethereum",
      "architecture": "Single-chain Nakamoto Consensus (PoW / PoS)",
      "comparison": "Traditional single-chain architectures discard forks to maintain global state consensus. Conflux keeps all valid forks, decoupling block generation from block ordering to scale throughput."
    },
    {
      "competitor": "Kaspa (GHOSTDAG / PHANTOM)",
      "architecture": "PoW blockDAG",
      "comparison": "Kaspa also uses a blockDAG to accept concurrent blocks and sorts them using k-cluster ordering. Conflux differentiates by using a dual-edge Tree-Graph (Tree + DAG) combined with GHAST, enabling advanced smart contract state execution rather than focusing primarily on peer-to-peer payments."
    },
    {
      "competitor": "Fantom (Lachesis) & Hedera (Hashgraph)",
      "architecture": "aBFT DAGs (PoS / Asynchronous)",
      "comparison": "Fantom and Hedera use leaderless, asynchronous Byzantine Fault Tolerant DAGs optimized for PoS. Conflux retains PoW-grade open-membership security for block proposal (supplemented with PoS finality through hybrid upgrades), avoiding the strict permissioning or centralized council structures seen in Hedera."
    },
    {
      "competitor": "Solana",
      "architecture": "Proof of History (PoH) Linear Pipeline",
      "comparison": "Solana scales by clock synchronization (PoH) and hardware-intensive parallel transaction execution (Sealevel). Conflux scales at the consensus topology layer, maintaining lower hardware entry barriers for validator nodes."
    }
  ]
}

